1	#!/usr/bin/env bash
2	# GRPO | Llama-3.2-1B-Instruct (dense) | FSDP + vLLM | DAPO-Math-17k
3	#
4	# Dense (LlamaForCausalLM), NOT MoE.
5	#
6	# Reward / advantage (defaults):
7	#   - algorithm.adv_estimator = grpo
8	#   - reward.reward_manager.name = dapo (overlong off by default)
9	#   - score: examples/grpo_trainer/reward_math_dapo_01.py::compute_score
10	#     (0/1: correct 1.0 / incorrect 0.0; same extract as math_dapo)
11	#   - trainer.resume_mode = disable  (always train from scratch unless overridden)
12	#   - DAPO filter_groups / dynamic sampling is NOT enabled (default null)
13	
14	set -euo pipefail
15	
16	# ---- logging / wandb ----
17	SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
18	VERL_ROOT="$(cd "${SCRIPT_DIR}/../.." && pwd)"
19	LOG_DIR="${LOG_DIR:-${VERL_ROOT}/logs}"
20	mkdir -p "${LOG_DIR}"
21	TIMESTAMP="$(date +%Y%m%d_%H%M%S)"
22	LOG_FILE="${LOG_DIR}/llama3_2_1b_instruct_dapo_math_fsdp_${TIMESTAMP}.log"
23	# Offline wandb: keep all run data local, no API key / network required.
24	# Logs land under ${WANDB_DIR}/wandb/ (sync later with `wandb sync` if desired).
25	export WANDB_MODE="${WANDB_MODE:-offline}"
26	export WANDB_DIR="${WANDB_DIR:-${LOG_DIR}}"
27	export WANDB_PROJECT="${WANDB_PROJECT:-verl_grpo_dapo_math}"
28	# Per-step metrics as JSONL, written unbuffered by verl's `file` tracking
29	# backend. The `console` backend prints the same numbers from inside the
30	# TaskRunner Ray actor, and whether Ray forwards that actor's stdout to the
31	# driver (and hence into LOG_FILE) varies with the Ray build, so the text log
32	# is not a dependable record of the metrics. This file always is.
33	export VERL_FILE_LOGGER_PATH="${VERL_FILE_LOGGER_PATH:-${LOG_DIR}/metrics_${TIMESTAMP}.jsonl}"
34	# ---- end logging / wandb ----
35	
36	# Resolve model path for host / docker.
37	if [[ -z "${MODEL_PATH:-}" ]]; then
38	    if [[ -d /models/Llama-3.2-1B-instruct ]]; then
39	        MODEL_PATH=/models/Llama-3.2-1B-instruct
40	    elif [[ -d /workspace/verl/Llama-3.2-1B-instruct ]]; then
41	        MODEL_PATH=/workspace/verl/Llama-3.2-1B-instruct
42	    else
43	        MODEL_PATH="${VERL_ROOT}/verl/Llama-3.2-1B-instruct"
44	    fi
45	fi
46	
47	# Dataset: DAPO-Math-17k (verl parquet).
48	if [[ -z "${TRAIN_FILE:-}" ]]; then
49	    if [[ -f /workspace/DAPO-Math-17k_verl/train.parquet ]]; then
50	        TRAIN_FILE=/workspace/DAPO-Math-17k_verl/train.parquet
51	    elif [[ -f /workspace/verl/datasets/DAPO-Math-17k_verl/train.parquet ]]; then
52	        TRAIN_FILE=/workspace/verl/datasets/DAPO-Math-17k_verl/train.parquet
53	    else
54	        TRAIN_FILE=/datasets/DAPO-Math-17k_verl/train.parquet
55	    fi
56	fi
57	if [[ -z "${TEST_FILE:-}" ]]; then
58	    if [[ -f /workspace/DAPO-Math-17k_verl/test.parquet ]]; then
59	        TEST_FILE=/workspace/DAPO-Math-17k_verl/test.parquet
60	    elif [[ -f /workspace/verl/datasets/DAPO-Math-17k_verl/test.parquet ]]; then
61	        TEST_FILE=/workspace/verl/datasets/DAPO-Math-17k_verl/test.parquet
62	    else
63	        TEST_FILE=/datasets/DAPO-Math-17k_verl/test.parquet
64	    fi
65	fi
66	
67	NNODES=${NNODES:-1}
68	# 1B dense fits easily; 2 GPUs.
69	NGPUS_PER_NODE=${NGPUS_PER_NODE:-2}
70	
71	# 8 prompts x ROLLOUT_N=8 samples = 64 sequences per update, so GRPO groups
72	# mix correct and incorrect responses often enough to produce gradient at the
73	# ~3-10% base accuracy of this model on DAPO-Math.
74	TRAIN_BATCH_SIZE=${TRAIN_BATCH_SIZE:-8}
75	PPO_MINI_BATCH_SIZE=${PPO_MINI_BATCH_SIZE:-${TRAIN_BATCH_SIZE}}
76	PPO_MICRO_BATCH_SIZE_PER_GPU=${PPO_MICRO_BATCH_SIZE_PER_GPU:-1}
77	LOG_PROB_MICRO_BATCH_SIZE_PER_GPU=${LOG_PROB_MICRO_BATCH_SIZE_PER_GPU:-1}
78	MAX_PROMPT_LENGTH=${MAX_PROMPT_LENGTH:-1024}
79	MAX_RESPONSE_LENGTH=${MAX_RESPONSE_LENGTH:-1024}
80	
81	ACTOR_LR=${ACTOR_LR:-1e-6}
82	# KL loss off by default for this dense DAPO-Math run.
83	USE_KL_LOSS=${USE_KL_LOSS:-False}
84	KL_LOSS_COEF=${KL_LOSS_COEF:-0.0}
85	ENTROPY_COEFF=${ENTROPY_COEFF:-0}
86	
87	# Dense 1B: TP=1 (one full copy per rollout engine; with 2 GPUs -> DP=2)
88	ROLLOUT_TP=${ROLLOUT_TP:-1}
89	ROLLOUT_GPU_MEM_UTIL=${ROLLOUT_GPU_MEM_UTIL:-0.5}
90	ROLLOUT_N=${ROLLOUT_N:-8}
91	# Llama-3.2 HF config has max_position_embeddings=131072; MUST cap for vLLM.
92	ROLLOUT_MAX_MODEL_LEN=${ROLLOUT_MAX_MODEL_LEN:-$((MAX_PROMPT_LENGTH + MAX_RESPONSE_LENGTH))}
93	ROLLOUT_ENFORCE_EAGER=${ROLLOUT_ENFORCE_EAGER:-False}
94	
95	# DAPO overlong buffer (disabled by default; must be < max_response_length when enabled)
96	OVERLONG_BUFFER_ENABLE=${OVERLONG_BUFFER_ENABLE:-False}
97	OVERLONG_BUFFER_LEN=${OVERLONG_BUFFER_LEN:-512}
98	OVERLONG_PENALTY_FACTOR=${OVERLONG_PENALTY_FACTOR:-1.0}
99	
100	PROJECT_NAME=${PROJECT_NAME:-verl_grpo_dapo_math}
101	EXPERIMENT_NAME=${EXPERIMENT_NAME:-${BENCH_TASK_LEAF_ID:-__BENCH_TASK_ID__}}
102	# No checkpoints: this recipe is scored from logged metrics only.
103	SAVE_FREQ=${SAVE_FREQ:--1}
104	TEST_FREQ=${TEST_FREQ:-20}
105	TOTAL_EPOCHS=${TOTAL_EPOCHS:-15}
106	TOTAL_TRAINING_STEPS=${TOTAL_TRAINING_STEPS:-60}
107	
108	USE_V1=${USE_V1:-False}
109	# "auto" would resume from checkpoints/.../latest; default disable = from-scratch.
110	RESUME_MODE=${RESUME_MODE:-disable}
111	# 0/1 reward (vs math_dapo native +1/-1)
112	REWARD_FN_PATH=${REWARD_FN_PATH:-${SCRIPT_DIR}/reward_math_dapo_01.py}
113	REWARD_FN_NAME=${REWARD_FN_NAME:-compute_score}
114	
115	########################### parameter arrays ###########################
116	
117	DATA=(
118	    algorithm.adv_estimator=grpo
119	    algorithm.use_kl_in_reward=False
120	    data.train_files=${TRAIN_FILE}
121	    data.val_files=${TEST_FILE}
122	    data.train_batch_size=${TRAIN_BATCH_SIZE}
123	    data.max_prompt_length=${MAX_PROMPT_LENGTH}
124	    data.max_response_length=${MAX_RESPONSE_LENGTH}
125	    data.filter_overlong_prompts=True
126	    data.truncation='error'
127	    data.dataloader_num_workers=0
128	)
129	
130	REWARD=(
131	    reward.reward_manager.name=dapo
132	    reward.custom_reward_function.path=${REWARD_FN_PATH}
133	    reward.custom_reward_function.name=${REWARD_FN_NAME}
134	    +reward.reward_kwargs.overlong_buffer_cfg.enable=${OVERLONG_BUFFER_ENABLE}
135	    +reward.reward_kwargs.overlong_buffer_cfg.len=${OVERLONG_BUFFER_LEN}
136	    +reward.reward_kwargs.overlong_buffer_cfg.penalty_factor=${OVERLONG_PENALTY_FACTOR}
137	    +reward.reward_kwargs.overlong_buffer_cfg.log=False
138	    +reward.reward_kwargs.max_resp_len=${MAX_RESPONSE_LENGTH}
139	)
140	
141	MODEL=(
142	    actor_rollout_ref.model.path=${MODEL_PATH}
143	    actor_rollout_ref.model.use_remove_padding=True
144	    actor_rollout_ref.model.enable_gradient_checkpointing=True
145	)
146	
147	ACTOR=(
148	    actor_rollout_ref.actor.optim.lr=${ACTOR_LR}
149	    actor_rollout_ref.actor.ppo_mini_batch_size=${PPO_MINI_BATCH_SIZE}
150	    actor_rollout_ref.actor.ppo_micro_batch_size_per_gpu=${PPO_MICRO_BATCH_SIZE_PER_GPU}
151	    actor_rollout_ref.actor.use_kl_loss=${USE_KL_LOSS}
152	    actor_rollout_ref.actor.kl_loss_coef=${KL_LOSS_COEF}
153	    actor_rollout_ref.actor.kl_loss_type=low_var_kl
154	    actor_rollout_ref.actor.entropy_coeff=${ENTROPY_COEFF}
155	    actor_rollout_ref.actor.fsdp_config.param_offload=False
156	    actor_rollout_ref.actor.fsdp_config.optimizer_offload=False
157	)
158	
159	ROLLOUT=(
160	    actor_rollout_ref.rollout.name=vllm
161	    actor_rollout_ref.rollout.tensor_model_parallel_size=${ROLLOUT_TP}
162	    actor_rollout_ref.rollout.gpu_memory_utilization=${ROLLOUT_GPU_MEM_UTIL}
163	    actor_rollout_ref.rollout.n=${ROLLOUT_N}
164	    actor_rollout_ref.rollout.max_model_len=${ROLLOUT_MAX_MODEL_LEN}
165	    actor_rollout_ref.rollout.enforce_eager=${ROLLOUT_ENFORCE_EAGER}
166	    actor_rollout_ref.rollout.enable_chunked_prefill=False
167	    actor_rollout_ref.rollout.free_cache_engine=True
168	    actor_rollout_ref.rollout.log_prob_micro_batch_size_per_gpu=${LOG_PROB_MICRO_BATCH_SIZE_PER_GPU}
169	)
170	
171	REF=(
172	    actor_rollout_ref.ref.log_prob_micro_batch_size_per_gpu=${LOG_PROB_MICRO_BATCH_SIZE_PER_GPU}
173	    actor_rollout_ref.ref.fsdp_config.param_offload=True
174	)
175	
176	TRAINER=(
177	    trainer.critic_warmup=0
178	    # file: per-step JSONL at VERL_FILE_LOGGER_PATH, the authoritative record.
179	    # console: same numbers to the TaskRunner's stdout (only reaches LOG_FILE
180	    #   when the Ray build forwards actor stdout to the driver).
181	    # wandb: offline run under WANDB_DIR/wandb.
182	    trainer.logger='["file","console","wandb"]'
183	    trainer.project_name=${PROJECT_NAME}
184	    trainer.experiment_name=${EXPERIMENT_NAME}
185	    trainer.n_gpus_per_node=${NGPUS_PER_NODE}
186	    trainer.nnodes=${NNODES}
187	    trainer.save_freq=${SAVE_FREQ}
188	    trainer.test_freq=${TEST_FREQ}
189	    trainer.total_epochs=${TOTAL_EPOCHS}
190	    trainer.total_training_steps=${TOTAL_TRAINING_STEPS}
191	    trainer.use_v1=${USE_V1}
192	    trainer.resume_mode=${RESUME_MODE}
193	)
194	
195	EXTRA=(
196	)
197	
198	########################### launch ###########################
199	echo "Logging to ${LOG_FILE} (no console training output)"
200	echo "MODEL_PATH=${MODEL_PATH}"
201	echo "TRAIN_FILE=${TRAIN_FILE} TEST_FILE=${TEST_FILE}"
202	echo "adv=grpo reward_manager=dapo score=0/1(${REWARD_FN_PATH}) resume_mode=${RESUME_MODE} max_model_len=${ROLLOUT_MAX_MODEL_LEN}"
203	export PYTHONPATH="${VERL_ROOT}:${PYTHONPATH:-}"
204	
205	python3 -m verl.trainer.main_ppo \
206	    "${DATA[@]}" \
207	    "${REWARD[@]}" \
208	    "${MODEL[@]}" \
209	    "${ACTOR[@]}" \
210	    "${ROLLOUT[@]}" \
211	    "${REF[@]}" \
212	    "${TRAINER[@]}" \
213	    "${EXTRA[@]}" \
214	    "$@" \
215	    >"${LOG_FILE}" 2>&1
216

